INSERT INTO notice (id, title, content, publisher_id, published_at, status, created_at, updated_at) VALUES
(1, '关于中山路口信号灯配时优化调整的公告', '为缓解早高峰拥堵，自本月起中山路口启用感应自适应配时方案，早晚高峰周期将在 80-120 秒间动态调整，请广大驾驶人按信号灯指示通行。', 1, '2026-09-04 21:16:33', 1, '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(2, '城东区新增两处违停严管路段', '即日起，朝阳路北段、新华路东段列为违停严管路段，违停车辆将被依法抓拍处罚，请规范停车。', 1, '2026-09-07 21:16:33', 1, '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(3, '市政广场地下停车场收费调整通知', '市政广场地下停车场自下月 1 日起执行新计费标准：免费时长 15 分钟，首小时 5 元，之后每小时 3 元，单日封顶 40 元。', 1, '2026-09-10 23:16:33', 1, '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(4, '智慧交通平台上线公告', '智慧交通综合管理服务平台正式上线，市民用户可查询路况、违章与停车场信息，欢迎体验并提交反馈。', 1, '2026-09-13 16:16:33', 1, '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(5, '周五晚高峰出行提示', '本周五晚高峰预计流量上升约 15%，建议错峰出行或选择公共交通，实时路况请查看平台数据大屏。', 1, '2026-09-16 23:16:33', 1, '2026-09-20 01:16:33', '2026-09-20 01:16:33');
INSERT INTO feedback (id, user_id, title, content, reply, status, handler_id, handled_at, created_at, updated_at) VALUES
(1, 3, '中山路口早高峰绿灯太短', '中山路口早高峰南北方向绿灯只有 20 秒，行人来不及过街，希望调整配时。', '已转信号配时部门核查，将于本周内优化。', 'resolved', 2, '2026-09-12 12:16:33', '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(2, 3, '万达广场停车场出口拥堵', '晚高峰万达停车场出口排队严重，建议增开出出口通道。', '已协调物业增开临时出口。', 'resolved', 2, '2026-09-04 22:16:33', '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(3, 3, '人民路口行人信号灯损坏', '人民路口东北角行人信号灯不亮，存在安全隐患。', NULL, 'processing', NULL, NULL, '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(4, 3, '新华路东段夜间大货车噪音', '夜间有大量大货车通行，噪音扰民，建议限行。', NULL, 'pending', NULL, NULL, '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(5, 3, '建议增加共享单车停放区', '地铁站周边共享单车乱停放，建议划定专门停放区。', NULL, 'pending', NULL, NULL, '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(6, 3, '建设路口标线不清晰', '建设路口左转导向标线磨损严重，雨天难以辨认。', NULL, 'pending', NULL, NULL, '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(7, 3, '市政停车场充电桩不足', '新能源车越来越多，希望增加充电桩数量。', NULL, 'pending', NULL, NULL, '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(8, 3, '朝阳路口放学时段拥堵', '朝阳路口 17:00-18:00 接送孩子车辆集中，拥堵严重。', '已安排高峰期警力疏导。', 'resolved', 2, '2026-08-27 06:16:33', '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(9, 3, '反馈平台操作问题', '违章查询页面偶尔加载很慢。', NULL, 'processing', NULL, NULL, '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(10, 3, '解放路口摄像头补光过亮', '夜间补光灯太亮影响驾驶视线，建议调整角度。', NULL, 'pending', NULL, NULL, '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(11, 3, '建议开通路况微信推送', '希望支持微信订阅路况推送。', NULL, 'pending', NULL, NULL, '2026-09-20 01:16:33', '2026-09-20 01:16:33'),
(12, 3, '表扬交警同志', '和平路口执勤交警帮助老人过马路，特此表扬。', '感谢您的肯定，已转达。', 'resolved', 2, '2026-08-29 10:16:33', '2026-09-20 01:16:33', '2026-09-20 01:16:33');
